// JobFilter provides filtering for Job queries
type JobFilter struct {
	Id              *UUIDFilter
	Title           *StringFilter
	Step            *StringFilter
	Topic           *StringFilter
	Status          *StringFilter
	StatusEnteredAt *DateTimeFilter
	Version         *Int64Filter
	// BatchID allows filtering by foreign key
	BatchID *UUIDFilter
	// Batch keeps the rows whose batch is among the Batch rows
	// the filter finds (D90): one condition, the foreign key in the keys of
	// those rows.
	Batch *BatchFilter
	// AllOf keeps the rows every one of its filters finds, beside the
	// filter's other conditions (D99): each filter's conditions are ANDed
	// with them, so two AnyOf groups, each in a filter of its own, must
	// both hold. A filter of no condition adds none, and so does an empty
	// AllOf.
	AllOf []JobFilter
	// AnyOf keeps the rows any of its filters finds, each filter's
	// conditions ANDed and the filters ORed, beside the filter's other
	// conditions (D90). A filter of no condition keeps every row, and so
	// does an empty AnyOf.
	AnyOf []JobFilter
}

// JobUpdate provides fields that can be updated
type JobUpdate struct {
	Title        *string
	Step         *string
	StepSetNull  bool
	Topic        *string
	TopicSetNull bool
	// BatchID allows updating the foreign key for batch
	BatchID *types.IdentityUUID
	// UpdatedBy is automatically set if not provided and user is in context
	UpdatedBy *types.IdentityUUID
}

// NewJobSnapshotUpdate maps every mutable field from a complete
// Job value. It is intended for source-of-truth replacement flows;
// nullable zero values clear their columns instead of leaving stale data.
func NewJobSnapshotUpdate(input *types.Job) *JobUpdate {
	update := &JobUpdate{}
	if input == nil {
		return update
	}
	update.Title = &input.Title
	var zeroStep string
	if input.Step == zeroStep {
		update.StepSetNull = true
	} else {
		update.Step = &input.Step
	}
	var zeroTopic string
	if input.Topic == zeroTopic {
		update.TopicSetNull = true
	} else {
		update.Topic = &input.Topic
	}
	return update
}

// ApplyTo writes every set and SetNull field onto row. A nil receiver or row
// is a no-op. SetNull wins when both a value and SetNull are present.
func (u *JobUpdate) ApplyTo(row *types.Job) {
	if u == nil || row == nil {
		return
	}
	if u.Title != nil {
		row.Title = *u.Title
	}
	if u.StepSetNull {
		var zeroStep string
		row.Step = zeroStep
	} else if u.Step != nil {
		row.Step = *u.Step
	}
	if u.TopicSetNull {
		var zeroTopic string
		row.Topic = zeroTopic
	} else if u.Topic != nil {
		row.Topic = *u.Topic
	}
	if u.BatchID != nil {
		row.Batch.Id = u.BatchID
	}
}

// JobFilterConditions are the filter's conditions for a query of
// the caller's own, each column qualified by its table: each value is
// appended to args, its placeholder numbered after those already there.
// FindMany's WHERE is them joined by AND. A nil filter has none.
func JobFilterConditions(filter *JobFilter, args *[]any) []string {
	return filter.conditions(args, len(*args))
}

// buildWhereClause builds a WHERE clause from a JobFilter: its
// conditions joined by AND, or nothing when it has none.
func (f *JobFilter) buildWhereClause(args *[]interface{}, paramOffset int) string {
	conditions := f.conditions(args, paramOffset)
	if len(conditions) == 0 {
		return ""
	}
	return " WHERE " + strings.Join(conditions, " AND ")
}

